### Configuration Examples

```hcl
# Terraform: EKS Cluster with HIPAA Controls
module "hipaa_eks_cluster" {
  source = "terraform-aws-modules/eks/aws"

  cluster_name    = "gainwell-hipaa-phi-01"
  cluster_version = "1.29"

  # Private cluster - no public endpoint
  cluster_endpoint_private_access = true
  cluster_endpoint_public_access  = false

  # Envelope encryption with customer-managed KMS key
  cluster_encryption_config = {
    provider_key_arn = aws_kms_key.eks_hipaa.arn
    resources        = ["secrets"]
  }

  # Comprehensive logging
  enabled_cluster_log_types = ["api", "audit", "authenticator", "controllerManager", "scheduler"]

  # Private subnets only
  subnet_ids = module.vpc.private_subnets

  # Enhanced node security
  eks_managed_node_groups = {
    hipaa_nodes = {
      instance_types = ["c5.2xlarge", "r5.2xlarge"]

      # Encrypted boot disks
      block_device_mappings = {
        xvda = {
          device_name = "/dev/xvda"
          ebs = {
            encrypted   = true
            kms_key_id  = aws_kms_key.ebs_hipaa.arn
            volume_size = 100
            volume_type = "gp3"
          }
        }
      }

      # IMDSv2 required
      metadata_options = {
        http_endpoint               = "enabled"
        http_tokens                 = "required"
        http_put_response_hop_limit = 1
      }
    }
  }

  tags = {
    Compliance = "HIPAA"
    DataClass  = "PHI"
    Tier       = "Tier3-HIPAA"
  }
}
```
